const COUNTRY_PATH_PATTERN = /<path class="country ([^"]+)" d="([^"]+)"\s*\/>/g
const countryPaths = [...COUNTRY_PATH_MARKUP.matchAll(COUNTRY_PATH_PATTERN)].map(([, classes, d]) => ({ classes, d }))

type RouteDefinition = {
  d: string
  start: { x: number; y: number }
  control: { x: number; y: number }
  end: { x: number; y: number }
}

function buildRouteGeometry(definition: RouteDefinition) {
  const fineSampleCount = 720
  const presentationSampleCount = 120
  const fineSamples = [{ ...definition.start, distance: 0 }]
  let length = 0
  for (let index = 1; index <= fineSampleCount; index += 1) {
    const t = index / fineSampleCount
    const inverse = 1 - t
    const point = {
      x: inverse * inverse * definition.start.x + 2 * inverse * t * definition.control.x + t * t * definition.end.x,
      y: inverse * inverse * definition.start.y + 2 * inverse * t * definition.control.y + t * t * definition.end.y,
    }
    const previous = fineSamples[index - 1]
    length += Math.hypot(point.x - previous.x, point.y - previous.y)
    fineSamples.push({ ...point, distance: length })
  }

  let fineIndex = 1
  const samples = Array.from({ length: presentationSampleCount + 1 }, (_, index) => {
    const target = length * (index / presentationSampleCount)
    while (fineIndex < fineSamples.length - 1 && fineSamples[fineIndex].distance < target) fineIndex += 1
    const before = fineSamples[fineIndex - 1]
    const after = fineSamples[fineIndex]
    const span = after.distance - before.distance
    const progress = span ? (target - before.distance) / span : 0
    return {
      distance: target,
      x: before.x + (after.x - before.x) * progress,
      y: before.y + (after.y - before.y) * progress,
    }
  })
  return { ...definition, length, samples }
}

const ROUTE_GEOMETRY = {
  blueSouth: buildRouteGeometry({ d: 'M 898.21 711.44 Q 850.21 885.44 824.73 811.10', start: { x: 898.21, y: 711.44 }, control: { x: 850.21, y: 885.44 }, end: { x: 824.73, y: 811.10 } }),
  blueEurope: buildRouteGeometry({ d: 'M 824.73 811.10 Q 888.60 473.49 788.46 185.88', start: { x: 824.73, y: 811.10 }, control: { x: 888.60, y: 473.49 }, end: { x: 788.46, y: 185.88 } }),
  redSouth: buildRouteGeometry({ d: 'M 916.08 694.66 Q 940.08 884.66 824.73 811.10', start: { x: 916.08, y: 694.66 }, control: { x: 940.08, y: 884.66 }, end: { x: 824.73, y: 811.10 } }),
  redEurope: buildRouteGeometry({ d: 'M 824.73 811.10 Q 749.47 393.87 822.20 136.63', start: { x: 824.73, y: 811.10 }, control: { x: 749.47, y: 393.87 }, end: { x: 822.20, y: 136.63 } }),
} as const

export function AboutJourneyMap() {
  return <AboutJourneyCanvas countries={countryPaths} routeGeometry={ROUTE_GEOMETRY} />
}
